import path from 'node:path';

/**
 * Resolve a relative path need not exist on disk, but ensures it does not escape the root.
 * @param {string} root - Base path
 * @param {string} value - Path to resolve relative to root
 * @returns {string} - Absolute resolved path
 * @throws {Error} - If value is absolute or escapes the root via `..`
 */
export function resolveRelative(root, value) {
  if (path.isAbsolute(value)) {
    throw new Error(`Path escapes the workspace: ${value}`);
  }
  const resolved = path.resolve(root, value);
  const rel = path.relative(root, resolved);
  // path.relative will give a leading '..' if resolved is outside root.
  if (rel.startsWith('..' + path.sep) || rel === '..') {
    throw new Error(`Path escapes the workspace: ${value}`);
  }
  // If resolved equals root, that's fine.
  return resolved;
}

